import{_ as n,o as a,c as p,a2 as l}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"04e · Gemini 20s 预览执行表（A/B 片）","description":"","frontmatter":{},"headers":[],"relativePath":"lab/shuangyu-fries/04e-gemini-preview-v1.md","filePath":"lab/shuangyu-fries/04e-gemini-preview-v1.md","lastUpdated":1786291067000}'),e={name:"lab/shuangyu-fries/04e-gemini-preview-v1.md"};function t(i,s,c,o,d,r){return a(),p("div",null,[...s[0]||(s[0]=[l(`<h1 id="_04e-·-gemini-20s-预览执行表-a-b-片" tabindex="-1">04e · Gemini 20s 预览执行表（A/B 片） <a class="header-anchor" href="#_04e-·-gemini-20s-预览执行表-a-b-片" aria-label="Permalink to &quot;04e · Gemini 20s 预览执行表（A/B 片）&quot;">​</a></h1><blockquote><p>阶段 4 · 执行 ｜ 2026-08-09 ｜ <strong>内部工作文档，可直接粘贴使用</strong></p><p>给客户<strong>预览方向</strong>用：A/B 片各 20s。2026-08-09 决定 A/B 一律 20s；Prompt 统一<strong>中文</strong>，直接粘贴即可（某段质量不达标时把该段译回英文重跑）。</p><p><strong>不是成片底料</strong>——成片走 <a href="./04a-jimeng-v1">04a</a>–<a href="./04d-b-gemini-v1">04d</a>。这版的价值是让客户在物料等待期先看见节奏与调性。</p></blockquote><div class="warning custom-block"><p class="custom-block-title">长度决定：B 片与提案 v1.0 不一致</p><p><a href="./01-proposal">提案</a>对客写的是 B 片 6–10s。本版按内部新决定做 20s，<strong>下次对客沟通时同步更新</strong>（含投放位与优先级，<a href="./01-proposal#五-需要贵司确认的事项">待客户确认第 3 条</a>）。在客户确认前，20s 的 B 片只作内部与预览使用。</p></div><div class="warning custom-block"><p class="custom-block-title">发预览时必须对客户说清的三件事</p><ol><li>这是<strong>方向预览</strong>，包装、文字、落版在正式版全部替换为真实资产；</li><li>预览里<strong>没有包装印刷</strong>——B 片用无印刷纯色红杯代替，是有意为之，不是漏做；</li><li>工艺段（安静油面、多孔透光）是正式版的核心，请客户重点看这两处。</li></ol></div><h2 id="a-片-·-20s-16-9" tabindex="-1">A 片 · 20s（16:9） <a class="header-anchor" href="#a-片-·-20s-16-9" aria-label="Permalink to &quot;A 片 · 20s（16:9）&quot;">​</a></h2><h3 id="整段单条-首选" tabindex="-1">整段单条（首选） <a class="header-anchor" href="#整段单条-首选" aria-label="Permalink to &quot;整段单条（首选）&quot;">​</a></h3><p>一次粘贴、整段生成。若当前版本单次上限不足 20s：支持长视频 / extend 的用长视频；不支持则模型会压缩到自己的上限——此时这条当作「一眼看整体」的方向预览，<strong>完整 20s 走下方四段版</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>高端食品广告微距摄影，接近纪录片的真实质感，暖调，</span></span>
<span class="line"><span>轻微胶片颗粒，自然肤色与食物色彩，不过度锐化、不过度饱和，</span></span>
<span class="line"><span>商业级布光，实拍感，一条连续完成的片子。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>0-5s —— 一整颗新鲜马铃薯，表皮微带薄土，落在深色胡桃木案板上，</span></span>
<span class="line"><span>轻微弹跳一次；一把厚背主厨刀切入，乳白的切面渗出淀粉汁水；</span></span>
<span class="line"><span>切好的马铃薯条边缘带自然毛刺与不规则棱角，慢动作落下。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5-10s —— 马铃薯条悬浮在封闭钢制真空舱内几乎完全平静的浅金色油中，</span></span>
<span class="line"><span>只有极细密的小气泡缓慢上升；接着是薯条剖面的极致微距，</span></span>
<span class="line"><span>孔洞逐渐形成、连成疏松的海绵状多孔结构。无剧烈翻滚，无大量白色泡沫。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>10-15s —— 强逆光在一根浅金色薯条脆后方逐渐增强，</span></span>
<span class="line"><span>点亮多孔蜂窝状断面，孔洞边缘依次发亮；</span></span>
<span class="line"><span>随后两根指尖把它掰断——清脆的咔嚓声，细碎干爽的碎屑慢动作飞散。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>15-20s —— 一堆浅金（不是深褐）干爽哑光的薯条脆，带细小红色调味颗粒，</span></span>
<span class="line"><span>在深色石质台面上堆叠，更多薯条脆从上方缓慢落下；</span></span>
<span class="line"><span>镜头拉远，在堆叠上方留出干净的空白。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>音效：一声闷响「咚」，一下清脆的切入声，近乎安静与细微气泡破裂声，</span></span>
<span class="line"><span>一声响亮清脆的「咔嚓」，柔和的沙沙声，轻柔的收尾音乐。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不出现任何文字、logo、品牌标识、包装，不出现日文或中文字符，</span></span>
<span class="line"><span>不卡通，无 3D 渲染感。</span></span></code></pre></div><p><strong>验收</strong>：5–10s 段油面必须平静（翻滚即废）；10–15s 段先透光后咔嚓；15–20s 段浅金非深褐、上方留空。</p><h3 id="四段精确版-备路" tabindex="-1">四段精确版（备路） <a class="header-anchor" href="#四段精确版-备路" aria-label="Permalink to &quot;四段精确版（备路）&quot;">​</a></h3><p>整段单条跑不通 20s 时，<strong>按顺序跑 <a href="./04b-gemini-v1">04b · 四段 Prompt</a>，剪接即 20s</strong>，不另写第二份：</p><table tabindex="0"><thead><tr><th>段</th><th>内容</th><th>字幕落点（正式版加，预览不加）</th></tr></thead><tbody><tr><td>1</td><td>原薯鲜切（落、切、毛刺条）</td><td>「原薯鲜切」</td></tr><tr><td>2</td><td>低温真空（安静油面）</td><td>「80~90℃ 低温油炸」（钩子，待 2b）</td></tr><tr><td>3</td><td>所以它是脆的（透光→咔嚓）</td><td>「所以它是脆的」</td></tr><tr><td>4</td><td>成品质感 + 上方留空</td><td>主标题落版位</td></tr></tbody></table><p>预览阶段每段跑 2–3 条选优；验收红线同上（油面平静、浅金非深褐、毛刺、先透光后咔嚓）。</p><hr><h2 id="b-片-·-20s-9-16" tabindex="-1">B 片 · 20s（9:16） <a class="header-anchor" href="#b-片-·-20s-9-16" aria-label="Permalink to &quot;B 片 · 20s（9:16）&quot;">​</a></h2><p>8s 版只有「撕开→露出→咔嚓→落版」，撑 20s 需要把脆的证据链补进来：</p><table tabindex="0"><thead><tr><th>段</th><th>时长</th><th>内容</th><th>来源</th></tr></thead><tbody><tr><td>B1</td><td>5s</td><td>第一帧撕封口 + 杯口倾现</td><td>预览生成（纯色红杯）；正式版实拍替换</td></tr><tr><td>B2</td><td>5s</td><td>俯视露出 + 抽出一根</td><td>下方 Prompt 2</td></tr><tr><td>B3</td><td>5s</td><td>逆光透光 → 咔嚓</td><td>下方 Prompt 3</td></tr><tr><td>B4</td><td>5s</td><td>成品堆叠 + 素杯落版位</td><td>下方 Prompt 4</td></tr></tbody></table><p><strong>B1 · 撕封口（预览版，纯色红杯）</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>9:16 竖屏，高端食品广告片质感，接近纪录片的真实质感，暖调，</span></span>
<span class="line"><span>轻微胶片颗粒，自然肤色与食物色彩，不过度锐化、不过度饱和，</span></span>
<span class="line"><span>商业级布光，实拍感。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第一帧：手指捏住一个无印刷纯色红杯的铝箔封口拉沿，</span></span>
<span class="line"><span>一次连贯地撕开，封口内侧沾着一层薄薄的调味粉。</span></span>
<span class="line"><span>随后杯口倾向镜头，露出杯内浅金色的薯条脆。</span></span>
<span class="line"><span>杯身外壁只有纯红色，没有任何印刷。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>音效：铝箔「嘶啦」一声，半拍安静，轻微的沙沙声。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不出现任何文字、logo、品牌标识、包装印刷，不出现日文或中文字符，</span></span>
<span class="line"><span>不卡通，无 3D 渲染感。</span></span></code></pre></div><p>验收：杯身出现任何印刷/文字即废——<strong>宁可杯子素一点，不让假包装到客户眼前</strong>。</p><p><strong>B2 · 俯视露出 + 抽出一根</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>9:16 竖屏，高端食品广告片质感，接近纪录片的真实质感，暖调，</span></span>
<span class="line"><span>轻微胶片颗粒，自然肤色与食物色彩，不过度锐化、不过度饱和，</span></span>
<span class="line"><span>商业级布光，实拍感。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>俯视直下视角看进已开盖的杯口：银色卷边一圈，</span></span>
<span class="line"><span>杯内装满浅金色薯条脆，表面带细小红色调味颗粒，干爽哑光，无油光。</span></span>
<span class="line"><span>两根手指伸入杯中，慢动作抽出一根薯条脆，</span></span>
<span class="line"><span>多孔的表面质地被光勾出。背景深色。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>俯拍，微距，浅景深，柔和顶光 + 侧面一盏硬光勾边。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>音效：轻微的沙沙抽出声，一声轻脆响铺垫。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不出现任何文字、logo、品牌标识、包装印刷，不出现日文或中文字符，</span></span>
<span class="line"><span>不卡通，无 3D 渲染感。</span></span></code></pre></div><p>验收：杯口只有银色卷边与产品；抽出动作慢、稳，手指只入画两根。</p><p><strong>B3 · 逆光透光 → 咔嚓</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>9:16 竖屏，高端食品广告片质感，接近纪录片的真实质感，暖调，</span></span>
<span class="line"><span>轻微胶片颗粒，自然肤色与食物色彩，不过度锐化、不过度饱和，</span></span>
<span class="line"><span>商业级布光，实拍感。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>极致微距，主体在画面上三分之一：</span></span>
<span class="line"><span>强逆光在一根浅金色薯条脆后方逐渐增强，点亮多孔蜂窝状断面，</span></span>
<span class="line"><span>孔洞边缘依次发亮。随后两根指尖把它掰断——清脆的咔嚓声，</span></span>
<span class="line"><span>细碎干爽的碎屑慢动作向四周飞散。表面干爽哑光，无油光。</span></span>
<span class="line"><span>纯黑背景，强侧光。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>音效：安静的张力上升，然后全片最响的一声清脆「咔嚓」，细碎屑飞散声。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不出现任何文字、logo、品牌标识、包装，不出现日文或中文字符，</span></span>
<span class="line"><span>不卡通，无 3D 渲染感。</span></span></code></pre></div><p>验收：先透光、后咔嚓，顺序不能反；手部畸形即改跑无人版本（薯条脆自行折断）。</p><p><strong>B4 · 成品堆叠 + 素杯落版位</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>9:16 竖屏，高端食品广告片质感，接近纪录片的真实质感，暖调，</span></span>
<span class="line"><span>轻微胶片颗粒，自然肤色与食物色彩，不过度锐化、不过度饱和，</span></span>
<span class="line"><span>商业级布光，实拍感。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>一堆浅金（不是深褐）的薯条脆，带细小红色调味颗粒，</span></span>
<span class="line"><span>在深色石质台面上堆叠，更多薯条脆从上方缓慢落下。</span></span>
<span class="line"><span>堆旁立着一个无印刷的纯色红杯，杯身纯红、无印刷。</span></span>
<span class="line"><span>镜头拉远，在上方留出干净的空白，留给主标题。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>音效：薯条脆相互碰撞的柔和沙沙声，轻柔的收尾音乐。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不出现任何文字、logo、品牌标识、包装印刷，不出现日文或中文字符，</span></span>
<span class="line"><span>不卡通，无 3D 渲染感。</span></span></code></pre></div><p>验收：浅金非深褐；上方留空是给主标题与正式包装合成的位置。</p><hr><h2 id="剪接与交付" tabindex="-1">剪接与交付 <a class="header-anchor" href="#剪接与交付" aria-label="Permalink to &quot;剪接与交付&quot;">​</a></h2><ul><li>A 片 16:9、B 片 9:16，各段剪成一条 20s；段间硬切即可，<strong>不加转场特效</strong>；</li><li>B 片音效是主角：剪接时检查「嘶啦 → 半拍安静 → 咔嚓最响」的链条在成条后仍成立（Veo 原生音频跨段不连续时，按 <a href="./04c-b-jimeng-v1#音效是主角">04c 拟音表</a> 后期统一铺）；</li><li>每条跑 2–3 条选优，预览不追精修；采用与废片原因记进 <a href="./05-genlog">05 · 生成日志</a>。</li></ul><hr><p><strong>上一步</strong> ← <a href="./04d-b-gemini-v1">04d · B 片 Gemini 执行表</a> ｜ <strong>下一步</strong> → <a href="./05-genlog">05 · 生成日志</a></p>`,34)])])}const b=n(e,[["render",t]]);export{g as __pageData,b as default};
